		"id empty":         `{"app": "a", "revision": "r", "image": "i", "batchSize": 1, "clusters": [{"id": " "}]}`,
		"id missing":       `{"app": "a", "revision": "r", "image": "i", "batchSize": 1, "clusters": [{}]}`,
		"duplicate id":     `{"app": "a", "revision": "r", "image": "i", "batchSize": 1, "clusters": [{"id": "x"}, {"id": "x"}]}`,
